package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.nio.file.*;import javax.xml.parsers.DocumentBuilderFactory;import org.w3c.dom.*;
public class UiTextGoldenTest {
 @Test public void thirtySixFrozenTranslationsKeepTheirUtf8Bytes()throws Exception{JSONArray golden;try(java.io.InputStream stream=getClass().getResourceAsStream("/ui058-golden.json")){assertNotNull(stream);golden=new JSONArray(new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}assertEquals(36,golden.length());for(int i=0;i<golden.length();i++){JSONObject sample=golden.getJSONObject(i);boolean english=sample.getString("language").equals("en");Map<String,Integer> source=english?UiText.messages:UiText.englishMessages;List<String> keys=english?UiText.messageKeys:UiText.englishMessageKeys;Map<Integer,String> strings=strings(english?"values":"values-hu");String value=sample.getString("input");Integer exact=source.get(value);String actual=exact!=null?strings.get(exact):UiText.replaceFragments(value,source,keys,strings::get);assertArrayEquals(value,sample.getString("expected").getBytes(java.nio.charset.StandardCharsets.UTF_8),actual.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 @Test public void cachedOrdersExactlyMatchOldStableSort(){for(Map<String,Integer> source:List.of(UiText.messages,UiText.englishMessages)){List<String> expected=new ArrayList<>(source.keySet());expected.sort(Comparator.comparingInt(String::length).reversed());List<String> actual=source==UiText.messages?UiText.messageKeys:UiText.englishMessageKeys;assertEquals(expected,actual);try{actual.clear();fail();}catch(UnsupportedOperationException expectedError){}}}
 private Map<Integer,String> strings(String folder)throws Exception{Path path=Path.of("src/main/res",folder,"strings.xml");if(!Files.exists(path))path=Path.of("app").resolve(path);NodeList nodes=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(path.toFile()).getElementsByTagName("string");Map<Integer,String> values=new HashMap<>();for(int i=0;i<nodes.getLength();i++){Element element=(Element)nodes.item(i);int id=R.string.class.getField(element.getAttribute("name")).getInt(null);values.put(id,element.getTextContent().replace("\\'","'").replace("\"", ""));}return values;}
}
